{
  "mushroom": "Amanita phalloides (death cap)",
  "composition": [
    {
      "compound": "alpha-Amanitin (bicyclic octapeptide, amatoxin)",
      "amount": "~0.2 mg/g fresh weight (roughly 1–2 mg/g dry weight; ~5–10 mg per fruiting body)",
      "effect": "Irreversibly inhibits RNA polymerase II, blocking mRNA synthesis and causing delayed, often fatal liver and kidney failure (human lethal dose ~0.1 mg/kg)."
    },
    {
      "compound": "beta-Amanitin",
      "amount": "~0.03 mg/g fresh weight",
      "effect": "Inhibits RNA polymerase II with hepatotoxic and nephrotoxic action similar to, but somewhat weaker than, alpha-amanitin."
    },
    {
      "compound": "gamma-Amanitin",
      "amount": "unknown (minor amatoxin, trace levels)",
      "effect": "Blocks RNA polymerase II and contributes to the hepatotoxicity of the mushroom."
    },
    {
      "compound": "Amanin and amaninamide",
      "amount": "unknown (minor amatoxins)",
      "effect": "Sulfur-free amatoxin analogues that inhibit RNA polymerase II and damage hepatocytes."
    },
    {
      "compound": "Amanullinic acid / amanullin",
      "amount": "unknown (trace amatoxin analogues)",
      "effect": "Weakly binding amatoxin relatives with little practical toxicity to humans."
    },
    {
      "compound": "Phalloidin (bicyclic heptapeptide, phallotoxin)",
      "amount": "~0.2 mg/g dry weight",
      "effect": "Stabilizes F-actin and is highly toxic by injection, but is poorly absorbed from the gut and heat-labile, so it adds little to poisoning by ingestion."
    },
    {
      "compound": "Phallacidin",
      "amount": "unknown (phallotoxin, comparable order to phalloidin)",
      "effect": "Binds and stabilizes filamentous actin, causing hepatocyte damage parenterally but negligible oral toxicity."
    },
    {
      "compound": "Phallisin and phallisacin",
      "amount": "unknown (minor phallotoxins)",
      "effect": "Actin-binding peptides that are cytotoxic in vitro but essentially inactive when eaten."
    },
    {
      "compound": "Virotoxins (viroidin, alaviroidin, viroisin, desoxoviroidin)",
      "amount": "unknown (minor monocylic peptides)",
      "effect": "Bind actin and disrupt the cytoskeleton experimentally; not significant in human oral poisoning."
    },
    {
      "compound": "Phallolysin (hemolytic protein/lectin-like toxin)",
      "amount": "unknown",
      "effect": "Lyses red blood cells in vitro but is destroyed by heat and gastric digestion, so it is harmless in cooked or ingested material."
    },
    {
      "compound": "Trehalose (main soluble carbohydrate)",
      "amount": "~5 % of dry weight",
      "effect": "Digestible disaccharide energy source that can cause bloating or diarrhoea in trehalase-deficient people."
    },
    {
      "compound": "Mannitol and other polyols",
      "amount": "~2 % of dry weight",
      "effect": "Osmotically active sugar alcohol that may cause mild gastrointestinal upset in larger amounts."
    },
    {
      "compound": "Water",
      "amount": "~90 % of fresh weight",
      "effect": "Nutritionally inert; its high content means toxins are concentrated about tenfold on drying."
    }
  ]
}

